import { BaseLitElement, webComponent } from '@domg-wc/common';
import { vlHeading1, vlHeading2, vlHeading3, vlHeading4, vlHeading5, vlHeading6 } from '@domg-wc/components/atom';
import { css, CSSResult, html, TemplateResult } from 'lit';

// Elke constante is de CSS van één titelniveau: zet ze in een regel van de CSS van je eigen component.
@webComponent('my-component-with-headings')
export class MyComponentWithHeadings extends BaseLitElement {
    static get styles(): CSSResult[] {
        return [
            css`
                .my-heading-1 {
                    ${vlHeading1}
                }

                .my-heading-2 {
                    ${vlHeading2}
                }

                .my-heading-3 {
                    ${vlHeading3}
                }

                .my-heading-4 {
                    ${vlHeading4}
                }

                .my-heading-5 {
                    ${vlHeading5}
                }

                .my-heading-6 {
                    ${vlHeading6}
                }
            `,
        ];
    }

    render(): TemplateResult {
        return html`
            <div class="my-heading-1">Heading van grootte 1</div>
            <div class="my-heading-2">Heading van grootte 2</div>
            <div class="my-heading-3">Heading van grootte 3</div>
            <div class="my-heading-4">Heading van grootte 4</div>
            <div class="my-heading-5">Heading van grootte 5</div>
            <div class="my-heading-6">Heading van grootte 6</div>
        `;
    }
}
